<script setup>
import {computed,ref,nextTick,watch} from 'vue'
import {focusControl} from '../shared/focusControl.js'
import {randomUUID} from '../shared/uuid.js'
import OptionPicker from '../shared/components/OptionPicker.vue'
import HelpTip from '../shared/components/HelpTip.vue'
import {Badge,Button,Field,FieldLabel,FieldError,Input,Switch,Tabs,TabsList,TabsTrigger,Textarea} from '../shared/shadcn-ui.js'
const profile=defineModel({required:true})
const props=defineProps({variables:{type:Array,default:()=>[]},suites:{type:Array,default:()=>[]},targets:{type:Array,default:()=>[]},disabled:Boolean})
const selected=ref('default'),tab=ref('entry'),error=ref(''),headersInput=ref(null)
const defaults=a=>({mode:'none',path:'/login',body:'{}',token_pointer:'/data/token',header:'Authorization',prefix:'Bearer ',...a})
profile.value.auth=defaults(profile.value.auth)
for(const e of profile.value.entries||[])e.auth=defaults(e.auth)
const entry=computed(()=>profile.value.entries?.find(e=>e.key===selected.value))
watch(()=>entry.value?.kind,kind=>{if(kind==='dubbo'){entry.value.auth=defaults({});entry.value.path_prefix='';tab.value='entry'}})
const auth=computed(()=>entry.value?.auth||profile.value.auth)
const variableLabel=key=>'{{var.'+key+'}}'
const headers=ref(JSON.stringify(auth.value.headers||{},null,2))
const loginPlaceholder=computed(()=>auth.value.body_type==='form'?'username={{var.API_USER}}&password={{var.API_PASSWORD}}':JSON.stringify({username:'{{var.API_USER}}',password:'{{var.API_PASSWORD}}'}))
function flush(){try{const value=JSON.parse(headers.value||'{}');if(!value||Array.isArray(value)||typeof value!=='object'||Object.values(value).some(v=>typeof v!=='string'))throw Error();auth.value.headers=value;for(const item of [profile.value.auth,...(profile.value.entries||[]).map(e=>e.auth)]){if(item.expires_in_seconds===''||item.expires_in_seconds==null)delete item.expires_in_seconds}error.value='';return true}catch{error.value='请求头须为字符串键值 JSON 对象';tab.value='advanced';nextTick(()=>focusControl(headersInput.value));return false}}
function choose(key){if(!flush())return;selected.value=key;headers.value=JSON.stringify(auth.value.headers||{},null,2)}
function add(){if(!flush()||(profile.value.entries||[]).length>=10)return;const key='entry-'+randomUUID().slice(0,8);profile.value.entries||=[];profile.value.entries.push({key,label:'新入口',kind:'direct',base_url:'',path_prefix:'',auth:defaults({})});choose(key);tab.value='entry'}
function remove(){profile.value.entries=profile.value.entries.filter(e=>e.key!==selected.value);selected.value='default';headers.value=JSON.stringify(auth.value.headers||{},null,2);error.value='';tab.value='entry'}
defineExpose({flush})
</script>
<template><fieldset :disabled="disabled" class="min-w-0 space-y-5"><div class="flex flex-wrap items-end gap-3"><Field class="min-w-0 flex-1"><FieldLabel>配置入口</FieldLabel><OptionPicker :model-value="selected" @update:model-value="choose" aria-label="配置测试入口" :disabled="disabled" :options="[{value:'default',label:'默认入口与机器认证'},...(profile.entries||[]).map(e=>({value:e.key,label:e.label}))]"/></Field><Button variant="outline" :disabled="disabled||(profile.entries||[]).length>=10" @click="add">添加入口</Button><Button v-if="entry" variant="ghost" :disabled="disabled" @click="remove">移除入口</Button></div><Tabs v-model="tab"><TabsList><TabsTrigger value="entry">入口</TabsTrigger><TabsTrigger v-if="entry?.kind!=='dubbo'" value="auth">认证</TabsTrigger><TabsTrigger value="advanced">高级</TabsTrigger></TabsList></Tabs>
<div v-show="tab==='entry'" class="grid min-w-0 gap-4 sm:grid-cols-2"><Field class="sm:col-span-2"><FieldLabel>启用此环境接口测试</FieldLabel><Switch v-model="profile.enabled" :disabled="disabled"/></Field><template v-if="entry"><Field><FieldLabel>入口名称</FieldLabel><Input v-model="entry.label" aria-label="入口名称"/></Field><Field><FieldLabel>连接方式</FieldLabel><OptionPicker v-model="entry.kind" aria-label="入口连接方式" :disabled="disabled" :options="[{value:'direct',label:'直连'},{value:'gateway',label:'网关'},{value:'dubbo',label:'Dubbo'}]"/></Field><template v-if="entry.kind==='dubbo'"><Field><FieldLabel>Nacos 资源别名（可选）</FieldLabel><Input :model-value="entry.registry_alias" @update:model-value="value=>{entry.registry_alias=value;if(value)entry.base_url=''}" aria-label="Nacos 资源别名" placeholder="应用环境已绑定的 Nacos 别名"/></Field><Field><FieldLabel>Nacos 注册分组</FieldLabel><Input v-model="entry.registry_group" aria-label="Nacos 注册分组" placeholder="DEFAULT_GROUP"/></Field><Field v-if="!entry.registry_alias" class="sm:col-span-2"><FieldLabel>Dubbo 提供者地址</FieldLabel><Input v-model="entry.base_url" aria-label="Dubbo 提供者地址" placeholder="dubbo://主机:20880"/></Field></template><template v-else><Field><FieldLabel>业务 Base URL</FieldLabel><Input v-model="entry.base_url" aria-label="入口业务地址" placeholder="https://api.example.com"/></Field><Field><FieldLabel>业务路径前缀（可选）</FieldLabel><Input v-model="entry.path_prefix" aria-label="入口路径前缀" placeholder="/gateway/orders"/></Field></template></template><Field v-else class="sm:col-span-2"><FieldLabel>默认环境访问入口（可选）<HelpTip text="留空复用已绑定部署机器。默认认证用于原环境入口和机器目标；新增直连与网关入口分别配置认证。"/></FieldLabel><Input v-model="profile.base_url" aria-label="环境基础地址" placeholder="https://api.example.com/context"/></Field></div>
<div v-show="tab==='auth'" class="grid min-w-0 gap-4 sm:grid-cols-2"><Field :class="auth.mode==='none'?'sm:col-span-2':''"><FieldLabel>认证方式</FieldLabel><OptionPicker v-model="auth.mode" aria-label="认证方式" :disabled="disabled" :options="[{value:'none',label:'无需认证'},{value:'bearer',label:'引用已有 Token 变量'},{value:'login',label:'登录后获取 Token'}]"/></Field><Field v-if="auth.mode==='bearer'"><FieldLabel>Token 变量</FieldLabel><OptionPicker v-model="auth.token_variable" aria-label="Token 变量" :disabled="disabled" :options="variables"/></Field><template v-if="auth.mode==='login'"><Field><FieldLabel>登录参数格式</FieldLabel><OptionPicker :model-value="auth.body_type||'json'" @update:model-value="auth.body_type=$event" aria-label="登录参数格式" :disabled="disabled" :options="[{value:'json',label:'JSON'},{value:'form',label:'表单（URL 编码）'}]"/></Field><Field><FieldLabel>独立登录服务地址（可选）</FieldLabel><Input v-model="auth.base_url" aria-label="认证服务地址" placeholder="留空与当前测试目标相同"/></Field><Field><FieldLabel>登录接口路径</FieldLabel><Input v-model="auth.path" aria-label="登录接口路径" placeholder="/login"/></Field><Field class="sm:col-span-2"><FieldLabel>登录参数（凭据使用变量引用）</FieldLabel><Textarea v-model="auth.body" aria-label="登录请求正文" :rows="3" :placeholder="loginPlaceholder"/></Field><Field><FieldLabel>Token 在响应中的路径</FieldLabel><Input v-model="auth.token_pointer" aria-label="Token 提取路径" placeholder="/data/token"/></Field></template><template v-if="auth.mode!=='none'"><Field><FieldLabel>Token 注入位置</FieldLabel><OptionPicker :model-value="auth.injection||'header'" @update:model-value="auth.injection=$event" aria-label="Token 注入位置" :disabled="disabled" :options="[{value:'header',label:'请求头'},{value:'query',label:'查询参数'},{value:'cookie',label:'Cookie'}]"/></Field><Field v-if="auth.injection==='query'||auth.injection==='cookie'"><FieldLabel>Token 参数名</FieldLabel><Input v-model="auth.name" aria-label="Token 参数名"/></Field><Field v-else><FieldLabel>携带 Token 的请求头</FieldLabel><Input v-model="auth.header" aria-label="Token 请求头" placeholder="Authorization"/></Field><Field v-if="auth.injection!=='cookie'"><FieldLabel>Token 前缀</FieldLabel><Input v-model="auth.prefix" aria-label="Token 前缀" placeholder="Bearer 后有一个空格"/></Field></template></div>
<div v-show="tab==='advanced'" class="grid min-w-0 gap-4 sm:grid-cols-2"><template v-if="auth.mode==='login'"><Field><FieldLabel>登录身份响应路径（可选）</FieldLabel><Input v-model="auth.identity_pointer" aria-label="登录身份路径" placeholder="/data/account"/></Field><Field><FieldLabel>预期 Token 有效期（秒，可选）<HelpTip text="仅作配置说明，不缓存 Token；每次执行重新登录，不在业务失败后刷新重试。"/></FieldLabel><Input v-model.number="auth.expires_in_seconds" type="number" min="0" max="31536000" aria-label="Token 有效期"/></Field><Field class="sm:col-span-2"><FieldLabel>刷新方式</FieldLabel><Input readonly value="每次执行重新登录，不缓存 Token" aria-label="Token 刷新方式"/></Field></template><Field class="sm:col-span-2"><FieldLabel>登录请求头 JSON</FieldLabel><Textarea ref="headersInput" v-model="headers" aria-label="登录请求头" :rows="3" :aria-invalid="!!error"/><FieldError v-if="error">{{error}}</FieldError></Field><Field><FieldLabel>交付回归测试集（可选）</FieldLabel><OptionPicker v-model="profile.regression_suite_id" aria-label="交付回归测试集" :disabled="disabled" placeholder="不配置交付回归" :options="suites.filter(s=>s.visibility==='team').map(s=>({value:s.id,label:s.name+' · v'+s.revision}))" all-label="不限"/></Field><Field><FieldLabel>交付回归目标（可选）</FieldLabel><OptionPicker v-model="profile.regression_target_key" aria-label="交付回归目标" :disabled="disabled" :options="targets.map(t=>({value:t.key,label:t.label}))" all-label="不限"/></Field></div><div v-if="auth.mode!=='none'" class="flex flex-wrap items-center gap-2 border-t pt-4 text-sm text-muted-foreground"><span>可引用变量</span><Badge v-for="key in variables" :key="key" variant="secondary">{{variableLabel(key)}}</Badge><span v-if="!variables.length">请先在应用环境绑定加密变量</span></div></fieldset></template>
